let state={plans:[],sessions:[]},screen='dashboard',busy=false,seq=0;const pending=new Map(),embedded=parent!==window;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rpc(method,params){return new Promise((resolve,reject)=>{const id=++seq;pending.set(id,{resolve,reject});parent.postMessage({jsonrpc:'2.0',id,method,params},'*');setTimeout(()=>{if(pending.has(id)){pending.delete(id);reject(Error('ChatGPT-Verbindung unterbrochen'))}},20000)})}
addEventListener('message',e=>{if(e.source!==parent)return;const m=e.data;if(pending.has(m?.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result)}if(m?.method==='ui/notifications/tool-result'&&m.params?.structuredContent?.state){state=m.params.structuredContent.state;render()}});
async function call(name,args={}){let r;if(embedded){r=await rpc('tools/call',{name,arguments:args});if(r.isError)throw Error(r.content[0].text);r=r.structuredContent}else{const res=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,args})});r=await res.json();if(!res.ok)throw Error(r.error)}state=r.state;return r.result}
function toast(s){const t=document.querySelector('.toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),4000)}
async function save(name,args){if(busy)return;busy=true;try{const r=await call(name,args);render();return r}catch(e){toast(e.message)}finally{busy=false}}
function nav(v){screen=v;render();scrollTo(0,0)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>nav(b.dataset.view));document.querySelector('.theme-toggle').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light'};
const btn=(label,act,id='')=>`<button class="complete-set" data-act="${act}" data-id="${esc(id)}">${label} →</button>`;
const head=(small,title)=>`<header class="topbar"><div><p class="eyebrow">${small}</p><h1>${title}</h1></div></header>`;
function render(){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===screen));document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===screen));const s=state.sessions.find(s=>s.status==='active'),history=state.sessions.filter(s=>s.status==='completed');
document.querySelector('#dashboard').innerHTML=head('DEIN TRAINING. DEIN FORTSCHRITT.','Stärker. <em>Satz für Satz.</em>')+`<div class="hero-grid"><article class="next-workout"><div class="ambient"></div><span class="pill live">${s?'TRAINING LÄUFT':'DEIN NÄCHSTER SCHRITT'}</span><div class="hero-copy"><p>GYM MASTERY</p><h2>${s?esc(s.planName):'Dein Plan.<br><span>Dein Moment.</span>'}</h2><p class="sub">${s?s.sets.length+' Sätze gespeichert':state.plans.length+' eigene Trainingspläne'}</p></div>${btn(s?'Training fortsetzen':'Neuen Trainingsplan erstellen',s?'resume':'new')}</article><div class="side-stack"><article class="coach-card"><p class="eyebrow">DEIN TRAINER IN CHATGPT</p><h3>Du trainierst.<br>Dein Coach denkt mit.</h3><p>Erstelle Trainingspläne, stelle Fragen und erfasse deine Sätze im Gespräch. Deine Web-App zeigt dieselben Daten.</p><p>„Zeig mir meine Trainingspläne“<br>„50 kg, 10 Wiederholungen, 2 RIR“</p></article><article class="week-card"><p class="eyebrow">TATSÄCHLICH GESPEICHERT</p><h3>${history.length} Trainings</h3><p>${state.sessions.reduce((n,x)=>n+x.sets.length,0)} Arbeitssätze</p></article></div></div><div class="section-head" style="margin:32px 0 18px"><h2>Meine Trainingspläne</h2><button class="finish-button" data-act="new">+ Neuer Plan</button></div><div class="plan-grid">${state.plans.map(p=>`<article class="coach-card"><p class="eyebrow">${p.exercises.length} ÜBUNGEN · VERSION ${p.version}</p><h3>${esc(p.name)}</h3><p>${p.exercises.map(e=>esc(e.name)).join(' · ')}</p>${btn('Plan ansehen','plan',p.id)}</article>`).join('')||'<article class="coach-card"><h3>Hier beginnt deine Geschichte.</h3><p>Erstelle deinen ersten Plan hier oder mit deinem Trainer in ChatGPT.</p></article>'}</div>`;
if(s){const e=s.exercises.find(e=>s.sets.filter(x=>x.exerciseId===e.id).length<e.sets)||s.exercises.at(-1),done=s.sets.filter(x=>x.exerciseId===e.id);const previous=history.slice().reverse().flatMap(x=>x.sets.filter(z=>x.exercises.find(y=>y.id===z.exerciseId)?.name===e.name));const last=done.at(-1)||previous.at(-1);document.querySelector('#workout').innerHTML=head(esc(s.planName),esc(e.name))+`<div class="workout-layout"><article class="exercise-panel"><p class="eyebrow">${done.length} VON ${e.sets} SÄTZEN GESCHAFFT</p><div class="target-card"><span>HEUTIGES ZIEL</span><div><strong>${e.minReps}–${e.maxReps} Wiederholungen</strong></div><p>Saubere Technik · kontrolliertes Tempo</p></div><div class="last-performance"><span>ZULETZT</span><b>${last?last.weight+' '+last.unit+' × '+last.reps:'Noch keine Leistung gespeichert'}</b></div><form id="set-form"><div class="input-zone"><label class="stepper">GEWICHT<input name="weight" type="number" min="0" max="1000" step="0.5" value="${last?.weight??20}" required><select name="unit" aria-label="Gewichtseinheit"><option ${last?.unit!=='lb'?'selected':''}>kg</option><option ${last?.unit==='lb'?'selected':''}>lb</option></select></label><label class="stepper">WIEDERHOLUNGEN<input name="reps" type="number" min="1" max="100" value="${e.minReps}" required></label></div><label class="field">Wiederholungen im Tank (RIR)<select name="rir"><option value="">Nicht angegeben</option>${[0,1,2,3,4,5].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><input type="checkbox" name="pain"> Schmerzen bei diesem Satz</label><button class="complete-set">✓ Satz dauerhaft speichern</button></form><div class="set-history">${done.map((z,i)=>`<p>✓ Satz ${i+1}<b>${z.weight} ${z.unit} × ${z.reps}</b></p>`).join('')}</div><button class="finish-button" data-act="finish">Training abschließen</button></article><aside class="rest-panel"><p class="eyebrow">PAUSENTIMER</p><div class="timer"><div><b id="rest-time">02:00</b><span>ERHOLUNG GEHÖRT DAZU</span></div></div><button class="finish-button" data-act="timer">2 Minuten starten</button>${btn('Progression prüfen','recommend',e.id)}<p id="recommendation" role="status"></p><div class="next-up"><span>DEINE ÜBUNGEN</span>${s.exercises.map(x=>`<p>${esc(x.name)} · ${s.sets.filter(z=>z.exerciseId===x.id).length}/${x.sets}</p>`).join('')}</div></aside></div>`;document.querySelector('#set-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),requestId=ev.target.dataset.requestId||crypto.randomUUID();ev.target.dataset.requestId=requestId;const r=await save('log_set',{sessionId:s.id,exerciseId:e.id,requestId,weight:Number(f.get('weight')),reps:Number(f.get('reps')),unit:f.get('unit'),...(f.get('rir')!==''?{rir:Number(f.get('rir'))}:{}),pain:f.get('pain')==='on'});if(r)toast('Satz gespeichert. Stark.')};
}else document.querySelector('#workout').innerHTML=head('DEIN TRAINING','Bereit, wenn <em>du es bist.</em>')+'<article class="coach-card"><h3>Wähle einen Trainingsplan.</h3>'+btn('Meine Trainingspläne','home')+'</article>';
document.querySelector('#progress').innerHTML=head('DEINE ECHTEN LEISTUNGEN','Fortschritt, <em>sichtbar.</em>')+`<div class="plan-grid">${history.slice().reverse().map(x=>`<article class="coach-card"><p class="eyebrow">${new Date(x.startedAt).toLocaleDateString('de-DE')}</p><h3>${esc(x.planName)}</h3><p>${x.sets.length} Arbeitssätze</p>${x.sets.map(z=>`<p>${esc(x.exercises.find(e=>e.id===z.exerciseId)?.name)} <b>${z.weight} ${z.unit} × ${z.reps}</b></p>`).join('')}</article>`).join('')||'<article class="coach-card"><h3>Jeder Satz wird Teil deiner Geschichte.</h3><p>Nach dem ersten abgeschlossenen Training erscheinen hier deine Leistungen.</p></article>'}</div>`;bind();}
function dialog(html){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML='<button class="dialog-close" aria-label="Schließen">×</button>'+html;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.showModal();return d}
function newPlan(){const d=dialog(`<p class="eyebrow">DEIN NÄCHSTES KAPITEL</p><h2>Neuer Trainingsplan</h2><form id="plan-form"><label class="field">Name<input name="name" maxlength="100" placeholder="Oberkörper A" required></label><label class="field">Übungen<textarea name="exercises" rows="6" placeholder="Bankdrücken; 3; 8; 12&#10;Rudern; 3; 8; 12" required></textarea></label><p>Pro Zeile: Name; Sätze; Wiederholungen von; bis.</p><p>Du kannst deinen Plan auch im Gespräch mit GYM MASTERY in ChatGPT erstellen.</p><button class="complete-set">Plan speichern</button><p role="alert" id="error"></p></form>`);d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),exercises=f.get('exercises').split('\n').filter(x=>x.trim()).map(x=>{const [name,sets,minReps,maxReps]=x.split(';');return {name:name.trim(),sets:Number(sets),minReps:Number(minReps),maxReps:Number(maxReps)}});const p=await save('create_training_plan',{name:f.get('name'),exercises});if(p){d.close();toast('Plan gespeichert')}else d.querySelector('#error').textContent='Bitte die Übungszeilen und Werte prüfen.'}}
let restEnd=0;setInterval(()=>{const t=document.querySelector('#rest-time');if(t&&restEnd){const n=Math.max(0,Math.ceil((restEnd-Date.now())/1000));t.textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}},1000);
function bind(){document.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{const a=b.dataset.act,s=state.sessions.find(s=>s.status==='active');if(a==='home')nav('dashboard');if(a==='resume')nav('workout');if(a==='new')newPlan();if(a==='plan'){const p=state.plans.find(p=>p.id===b.dataset.id);dialog(`<p class="eyebrow">DEIN TRAININGSPLAN</p><h2>${esc(p.name)}</h2>${p.exercises.map(e=>`<div class="plan-exercise"><b>${esc(e.name)}</b><span>${e.sets} × ${e.minReps}–${e.maxReps} Wdh.</span></div>`).join('')}${btn('Training starten','start',p.id)}`);bind()}if(a==='start'){const r=await save('start_workout',{planId:b.dataset.id});if(r){document.querySelector('dialog')?.close();nav('workout')}}if(a==='finish'){const r=await save('finish_workout',{sessionId:s.id});if(r){toast('Training abgeschlossen. Jeder Satz zählt.');nav('progress')}}if(a==='timer')restEnd=Date.now()+120000;if(a==='recommend'){const r=await save('get_progression_recommendation',{sessionId:s.id,exerciseId:b.dataset.id});if(r)document.querySelector('#recommendation').textContent=r.reason}})}
let loaded=false;
async function refresh(){try{const before=JSON.stringify(state);await call('get_user_training_context');if(!loaded||before!==JSON.stringify(state)){loaded=true;render()}}catch(e){if(loaded){toast('Verbindung unterbrochen. Gespeicherte Daten bleiben erhalten.');return}document.querySelector('#dashboard').innerHTML=head('GYM MASTERY','Dein Training.<br><em>Dauerhaft verbunden.</em>')+`<article class="coach-card"><h3>Verbindung herstellen</h3><p>${esc(e.message)}</p><a class="start-button" href="/signin-with-chatgpt" target="_top">Mit ChatGPT anmelden →</a></article>`}}
if(embedded)rpc('ui/initialize',{appInfo:{name:'GYM MASTERY',version:'1.0.0'},appCapabilities:{},protocolVersion:'2026-01-26'}).then(()=>{parent.postMessage({jsonrpc:'2.0',method:'ui/notifications/initialized'},'*');refresh()}).catch(e=>toast(e.message));else refresh();
